1	// Tập 7 · C4 · ĐOẠN G = S29–S33. Leo (ILLUSTRATIVE, màu riêng, BÊN TRÁI Tessa) mọc cùng nhà; chồng của Leo thấp, hộp cushion rộng, thanh thấp — cạnh cụm
2	// của Tessa (chồng cao, thanh cao) → ô thứ ba trống (thanh trống, chồng trống: "your bar", "your stack") → thẻ phương pháp V7 → khung cold open: hai thẻ
3	// khoản vay trượt vào nhau thành "30-year paid in 15 = 15-year + a fallback", "week of Oct 8, 2026: $120 a month". Mốc giờ chỉ từ spine.json.
4	import { setup, figure, gesture, figTag, OfferCard, theStack, stackSet, BUNDLE_TH, modeLook, followLight, chrome, label, seg2, dip, CHAR,
5	  kf, show, pulse, C, ease, lin, mix, THREE, setOpacity } from '/episodes/ep007/world/c4kit.js';
6	import { Beam } from '/toolkit/factory/world/lib3d.js';
7	
8	const SEG = '/episodes/ep007/world/c4/g-s29-s33/';
9	const PER_PCT = 0.3, GAP_U = 1 / 500;   // thanh: 0,3/điểm % (như S25); hộp cushion: 1/500 đơn vị mỗi $/tháng của khoảng chênh khoản trả
10	
11	export async function boot(res) {
12	  const poses = {
13	    wPair0: { pos: [-3.0, 3.2, 11.5], tgt: [-1.4, 1.1, 0], fov: 44, chart: 0 },
14	    cPair: { pos: [-2.0, 1.7, 19.14], tgt: [-2.0, 1.7, 0], fov: 20, chart: 1 },
15	    // cThree (C4 r4): lệch phải — ô thứ ba trọn trong khung, chừa lề phải cho dây dẫn của hai nhãn S31 (fov giữ 20: tên người không chạm thẻ V7)
16	    cThree: { pos: [0.0, 1.9, 24.24], tgt: [0.0, 1.9, 0], fov: 20, chart: 1 },
17	    wHome: { pos: [-2.2, 2.7, 8.6], tgt: [1.7, 0.9, 0], fov: 40, chart: 0 },
18	    cHome: { pos: [1.2, 2.2, 16.93], tgt: [1.2, 2.2, 0], fov: 22, chart: 1 },
19	  };
20	  const { S, D, G, cue, MV, st, O, renderer, scene, floor, key, CAM } = await setup(SEG, res, poses);
21	  const b = cue, X = S.x;
22	  const hm = figure(scene, { x: X.house }), leo = figure(scene, { x: X.leo_house, color: CHAR.leo, char: 'Leo' });
23	  const tStack = theStack(scene, G, { x: X.stack }), lStack = theStack(scene, G, { x: X.leo_stack });
24	  stackSet(tStack, G.stack_total); lStack.userData.checks.key = 'leo-stack'; lStack.userData.checks.char = 'Leo';
25	  const mkBeam = (x, key) => { const m = Beam({ length: 1.0 }); m.scale.set(1, 2.2, 1.4); m.position.x = x; scene.add(m); m.userData.checks = { role: 'mark', series: 'bar', key }; return m; };
26	  const tBar = mkBeam(X.bar, 'the-bar'), lBar = mkBeam(X.leo_bar, 'leo-bar'), blankBar = mkBeam(X.blank_bar, 'your-bar');
27	  tBar.position.y = G.bar * PER_PCT;
28	  const room = (x, gap) => { const m = new THREE.Mesh(new THREE.BoxGeometry(0.5, 1, 0.14), new THREE.MeshStandardMaterial({ color: C.cushion, emissive: new THREE.Color(C.cushion), emissiveIntensity: 0.45, transparent: true, depthWrite: false }));
29	    m.geometry.translate(0, 0.5, 0); m.position.set(x, 0, 1.0); m.userData.h = gap * GAP_U; m.userData.checks = { role: 'mark', key: `fallback-room-${x}`, value: gap }; scene.add(m); return m; };
30	  const lRoom = room(X.leo_house, S.gap.leo), tRoom = room(X.house, S.gap.tessa);
31	  // ô thứ ba (C4 r4): thanh trống / chồng trống chỉ còn lớp mờ rất nhẹ — hình chính là viền nét đứt vẽ ở lớp phủ (không đặc)
32	  const blankStack = new THREE.Mesh(new THREE.BoxGeometry(0.9, 2.0, 0.6), new THREE.MeshStandardMaterial({ color: C.muted, transparent: true, opacity: 0.06, depthWrite: false }));
33	  blankStack.position.set(X.blank_stack, 1.0, 0); scene.add(blankStack); blankStack.userData.checks = { role: 'mark', key: 'your-stack' };
34	  const card15 = OfferCard(scene, { x: X.cards[0], y: 4.0, w: 3.6, h: 0.8 }), card30 = OfferCard(scene, { x: X.cards[1], y: 4.0, w: 3.6, h: 0.8 }), cardM = OfferCard(scene, { x: X.merge, y: 4.0, w: 7.4, h: 0.9 });
35	  const leoH = leo.house, leoP = leo.person;
36	
37	  function frame(t) {
38	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
39	    followLight(key, pose.tgt); modeLook(scene, floor, cw); gesture(hm, t, S.gestures); gesture(leo, t, S.leo_gestures);
40	    // S29: nhà + Leo mọc ở "illustrative"
41	    const lv = ease(t, b.g0.illustrative - 0.1, b.g0.illustrative + 0.8);
42	    leoH.scale.set(1, Math.max(0.001, lv), 1); leoH.visible = lv > 0.01; leoP.scale.setScalar(Math.max(0.001, lv)); leoP.visible = lv > 0.01;
43	    stackSet(lStack, kf(S.leo_stack, t));
44	    // thanh: của Tessa đứng sẵn ở 7.40 % (từ đoạn f); của Leo trồi ở "bar" tới 2.65 %; thanh trống ở ô thứ ba
45	    const lu = ease(t, b.g3.bar - 0.02, b.g3.bar + 0.6); lBar.position.y = -0.12 + (0.12 + S.leo_bar * PER_PCT) * lu; lBar.visible = lu > 0.01;
46	    const glow = (m, ...ts) => m.glow(0.7 * Math.max(...ts.map(([a, d]) => pulse(t, a, d))), C.ink);
47	    glow(tBar, [b.g5.high, 1.0], [b.j0.high, 1.2], [b.h1.bar, 0.9]); glow(lBar, [b.g5.low, 1.0], [b.g3.earned, 1.0]);
48	    // S31.1: ô thứ ba hiện ở "Any" (đế trước, thanh + chồng trống ngay sau), loé ở "pair"
49	    const bA = ease(t, b.h0.any - 0.05, b.h0.any + 0.6) * (1 - ease(t, MV.m_w33.t0, MV.m_w33.t0 + 0.4)), oA = bA * ease(t, b.h0.any + 0.2, b.h0.any + 0.8);
50	    setOpacity(blankBar, 0.12 * oA); blankBar.position.y = 1.5; blankBar.visible = oA > 0.01; blankBar.glow(0.6 * pulse(t, b.h1.bar, 1.0), C.ink);
51	    blankStack.material.opacity = (0.06 + 0.12 * pulse(t, b.h1.stack, 1.0)) * oA; blankStack.visible = oA > 0.01;
52	    // hộp cushion (đường lui): Leo ở "room", Tessa ngay sau (nhỏ hơn); tắt khi về khung cold open
53	    const rEnd = 1 - ease(t, MV.m_w33.t0, MV.m_w33.t0 + 0.4);
54	    for (const [m, a] of [[lRoom, b.g2.room], [tRoom, b.g2.room + 0.3]]) { const u = ease(t, a - 0.05, a + 0.6) * rEnd; m.scale.y = Math.max(0.001, m.userData.h * u); m.visible = u > 0.01;
55	      m.material.opacity = 0.42 + 0.3 * (m === tRoom ? pulse(t, b.h2.fallback, 1.0) : 0); }
56	    // S33: hai thẻ → trượt vào nhau ở "plus" → một thẻ có dải cushion
57	    const mg = ease(t, b.j2.plus - 0.05, b.j2.plus + 0.8);
58	    card15.position.x = mix(X.cards[0], X.merge, mg); card30.position.x = mix(X.cards[1], X.merge, mg);
59	    card15.set({ a: show(t, b.j1.fifteen) * (1 - mg) }); card30.set({ a: show(t, b.j1.thirty) * (1 - mg) });
60	    cardM.set({ a: mg, band: ease(t, b.j2.fallback - 0.05, b.j2.fallback + 0.8) });
61	    renderer.render(scene, cam);
62	    // ---------------- lớp phủ
63	    const log = O.begin(t, cw, cam), ok = cw >= 0.95 ? 1 : 0; log.roi = {};
64	    dip(O, 1 - ease(t, 0, 0.4));
65	    const cardA = ok * show(t, b.i0.method, MV.m_w33.t0 - 0.05);
66	    dip(O, 0.72 * cardA);                     // thẻ V7: thế giới lùi sau, vẽ TRƯỚC mọi chữ
67	    figTag(O, hm); figTag(O, leo, lv * (1 - ease(t, MV.m_w33.t0, MV.m_w33.t0 + 0.3)));   // khung cold open (S33): chỉ Tessa
68	    const sc = (x, y, z = 0) => O.toScreen(x, y, z), p31 = MV.m_pan31.t0 - 0.05;
69	    { const [x, y] = sc(X.leo_house, 1.0); log.roi['g0.illustrative'] = [x - 200, y - 150, x + 200, y + 120]; }
70	    // S29–S30: nhãn của Leo (ba hàng trái), của Tessa (hàng phải)
71	    label(O, `Leo · ILLUSTRATIVE · ${D('r30_min_week_short')} · ${D('term_long')} at ${D('leo_r30')}`, 130, 205, { kind: 'number', alpha: ok * show(t, b.g0.lowest, p31), char: 'Leo',
72	      claims: ['r30_min_week_short', 'term_long', 'leo_r30'] });
73	    log.roi['g0.lowest'] = [120, 150, 1500, 230];
74	    { const [x, y] = sc(X.leo_stack, S.leo_total / G.bundle_usd * BUNDLE_TH), [, y0] = sc(X.leo_stack, 0); log.roi['g0.paid'] = [x - 70, y - 20, x + 70, y0];
75	      const [tx, ty] = sc(X.stack - 0.45, G.stack_total / G.bundle_usd * BUNDLE_TH), a = ok * show(t, b.g1.cheaper, p31);
76	      seg2(O, x + 60, y, mix(x + 60, tx, lin(t, b.g1.cheaper, b.g1.cheaper + 0.6)), y, C.ink, 0.8 * a, 4, [14, 10]);
77	      log.roi['g1.cheaper'] = [x - 70, y - 30, tx, y + 30]; }
78	    label(O, `Leo's stack: ${D('leo_extra_vs15_total')} (${D('leo_extra_vs15_month')})`, 130, 268, { kind: 'number', alpha: ok * show(t, b.g1.thirteen, p31), char: 'Leo',
79	      claims: ['leo_extra_vs15_total', 'leo_extra_vs15_month'] });
80	    log.roi['g1.thirteen'] = [120, 215, 1150, 290];
81	    label(O, `Leo: fallback ${D('leo_fallback_gap')}`, 130, 331, { kind: 'number', alpha: ok * show(t, b.g2.seven, p31), char: 'Leo', claims: ['leo_fallback_gap'] });
82	    log.roi['g2.seven'] = [120, 280, 1060, 350];
83	    { const [x, y] = sc(X.leo_house, 0, 1.0), [, y1] = sc(X.leo_house, S.gap.leo * GAP_U, 1.0); log.roi['g2.room'] = [x - 60, y1 - 20, x + 60, y]; }
84	    { const [x, y] = sc(X.leo_bar, S.leo_bar * PER_PCT), [, y0] = sc(X.leo_bar, 0);
85	      label(O, `bar ${D('leo_r30')}`, Math.max(250, x), y - 44, { align: 'center', kind: 'number', alpha: ok * show(t, b.g3.two, p31), char: 'Leo', claims: ['leo_r30'] });
86	      log.roi['g3.bar'] = [x - 90, y - 20, x + 90, y0]; log.roi['g3.two'] = [x - 160, y - 90, x + 160, y - 30]; log.roi['g3.earned'] = log.roi['g3.bar'];
87	      log.roi['g5.low'] = log.roi['g3.bar']; }
88	    // S30.3: thẻ tuần trên mái hai nhà
89	    { const wA = ok * show(t, b.g4.different, p31), [lx, ly] = sc(X.leo_house, 1.75), [tx, ty] = sc(X.house, 1.75);
90	      label(O, D('r30_min_week_short'), lx, ly - 30, { align: 'center', kind: 'number', px: 48, alpha: wA, char: 'Leo', claims: ['r30_min_week_short'] });
91	      label(O, D('last_week_short'), tx, ty - 30, { align: 'center', kind: 'number', px: 48, alpha: wA, char: 'Tessa', claims: ['last_week_short'] });
92	      log.roi['g4.different'] = [lx - 140, ly - 80, lx + 140, ly - 15]; log.roi['g4.same'] = [sc(X.leo_bar - 0.6, 0)[0], sc(0, 2.8)[1], sc(X.stack + 0.5, 0)[0], sc(0, 0)[1]]; }
93	    { const [x, y] = sc(X.leo_stack, S.leo_total / G.bundle_usd * BUNDLE_TH), [, y0] = sc(X.leo_stack, 0); log.roi['g5.short'] = [x - 70, y - 20, x + 70, y0]; }
94	    { const [x, y] = sc(X.stack, G.stack_total / G.bundle_usd * BUNDLE_TH), [, y0] = sc(X.stack, 0); log.roi['g5.tall'] = [x - 70, y - 20, x + 70, y0]; log.roi['j0.tall'] = log.roi['g5.tall']; }
95	    { const [x, y] = sc(X.bar, G.bar * PER_PCT); log.roi['g5.high'] = [x - 90, y - 30, x + 90, y + 30]; log.roi['j0.high'] = log.roi['g5.high']; }
96	    label(O, `Tessa · ILLUSTRATIVE: stack ${D('extra_vs15_total_now')} · bar ${D('r30_now')}`, 1800, 394, { align: 'right', kind: 'number', alpha: ok * show(t, b.g5.tessa, p31), char: 'Tessa',
97	      claims: ['extra_vs15_total_now', 'r30_now'] });
98	    log.roi['g5.tessa'] = [440, 345, 1800, 415];
99	    // S31 (C4 r4): ô thứ ba trống THẤY BẰNG HÌNH — đế cùng cỡ lô nhà (nền sáng nhẹ + viền sáng nét đứt trên sàn), trong đó chồng trống và thanh trống là
100	    // khối viền nét đứt (12 cạnh, không đặc); nét dày hơn khi lời gọi tên từng vật
101	    const [lc, lw, ld] = X.lot, poly = (P, a, lw0, fill) => { const c = O.ctx; c.save(); c.globalAlpha = a; c.beginPath(); P.forEach(([x, y], i) => (i ? c.lineTo(x, y) : c.moveTo(x, y))); c.closePath();
102	      if (fill) { c.fillStyle = C.ink; c.globalAlpha = a * fill; c.fill(); c.globalAlpha = a; } c.strokeStyle = C.ink; c.lineWidth = lw0; c.setLineDash([16, 10]); c.stroke(); c.restore(); };
103	    const wire = (x0, x1, y0, y1, z0, z1, a, lw0) => { const c = O.ctx, V = (i) => sc(i & 1 ? x1 : x0, i & 2 ? y1 : y0, i & 4 ? z1 : z0); c.save(); c.globalAlpha = a; c.strokeStyle = C.ink; c.lineWidth = lw0; c.setLineDash([10, 7]);
104	      c.beginPath(); for (const [i, j] of [[0, 1], [2, 3], [4, 5], [6, 7], [0, 2], [1, 3], [4, 6], [5, 7], [0, 4], [1, 5], [2, 6], [3, 7]]) { const [ax, ay] = V(i), [bx, by] = V(j); c.moveTo(ax, ay); c.lineTo(bx, by); } c.stroke(); c.restore(); };
105	    const fin = b.i0.method - 0.45;   // ba nhãn S31 (và dây dẫn) tắt hẳn trước khi thẻ V7 hiện
106	    const kA = 1 - cardA;   // C4 r4b: đế + khối viền ô thứ ba tắt khi thẻ V7 hiện (verify F-2: đường dưới chữ thẻ)
107	    if (bA * kA > 0.01) {
108	      const lotP = [[lc - lw / 2, -ld / 2], [lc + lw / 2, -ld / 2], [lc + lw / 2, ld / 2], [lc - lw / 2, ld / 2]].map(([x, z]) => sc(x, 0.01, z));
109	      poly(lotP, 0.95 * bA * kA, 4 + 3 * pulse(t, b.h0.pair, 1.0), 0.1);
110	      wire(X.blank_stack - 0.45, X.blank_stack + 0.45, 0, 2.0, -0.3, 0.3, 0.95 * oA * kA, 3 + 3 * pulse(t, b.h1.stack, 1.0));
111	      wire(X.blank_bar - 0.5, X.blank_bar + 0.5, 1.38, 1.62, -0.25, 0.25, 0.95 * oA * kA, 3 + 3 * pulse(t, b.h1.bar, 1.0));
112	    }
113	    { const xs = [-1, 1].flatMap((u) => [-1, 1].map((v) => sc(lc + u * lw / 2, 0, v * ld / 2)[0])), [, yT] = sc(X.blank_stack, 2.1), [, yB] = sc(lc, 0, ld / 2);
114	      log.roi['h0.any'] = [Math.min(...xs), yT, Math.max(...xs), yB]; log.roi['h0.pair'] = log.roi['h0.any']; }
115	    // hai nhãn (cột phải) + dây dẫn đi ở lề phải ngoài chữ: thanh (lề ngoài, x 1878) vào cạnh phải thanh trống; chồng (lề trong, x 1850) qua TRÊN đỉnh thanh
116	    // vào đỉnh chồng trống — hai dây không cắt nhau, không cắt chữ
117	    const aB = ok * show(t, b.h1.bar, fin), aS = ok * show(t, b.h1.stack, fin);
118	    label(O, "your bar = your loan's own rate", 1810, 205, { align: 'right', kind: 'name', alpha: aB });
119	    label(O, 'your stack = how far apart', 1810, 268, { align: 'right', kind: 'name', alpha: aS });
120	    { const lead = (P, a) => { if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = 0.9 * a; c.strokeStyle = C.ink; c.lineWidth = 3; c.beginPath();
121	        P.forEach(([x, y], i) => (i ? c.lineTo(x, y) : c.moveTo(x, y))); c.stroke(); const [ex, ey] = P[P.length - 1]; c.fillStyle = C.ink; c.beginPath(); c.arc(ex, ey, 7, 0, 2 * Math.PI); c.fill(); c.restore(); };
122	      const [bx, by] = sc(X.blank_bar + 0.5, 1.5), [sx, sy] = sc(X.blank_stack, 2.0), yS = Math.min(sy - 22, sc(X.blank_bar, 1.62)[1] - 30);
123	      lead([[1818, 191], [1878, 191], [1878, by], [bx + 6, by]], aB);
124	      lead([[1818, 254], [1850, 254], [1850, yS], [sx, yS], [sx, sy - 4]], aS); }
125	    label(O, `the ${D('term_short')} and ${D('term_long')} offers sit`, 1810, 331, { align: 'right', kind: 'number', alpha: ok * show(t, b.h1.stack, fin), claims: ['term_short', 'term_long'] });
126	    log.roi['h1.bar'] = [900, 150, 1810, 230]; log.roi['h1.stack'] = [800, 215, 1810, 350];
127	    label(O, 'a dollar in the house is hard to get back', 1810, 394, { align: 'right', kind: 'compare', alpha: ok * show(t, b.h2.hard, fin) });
128	    log.roi['h2.hard'] = [600, 345, 1810, 415];
129	    { const [x, y] = sc(X.house, 1.0); log.roi['h2.house'] = [x - 200, y - 150, x + 200, y + 120]; const [rx, ry] = sc(X.house, 0, 1.0); log.roi['h2.fallback'] = [rx - 60, ry - 160, rx + 60, ry]; }
130	    // S32: thẻ phương pháp V7 (tiêu đề + 9 dòng, giữ qua cả hai câu)
131	    if (cardA > 0.01) {
132	      O.card(120, 140, 1680, 680, { fill: '#11161E', stroke: '#3A4250', lw: 3, alpha: 0.96 * cardA });
133	      label(O, 'How we know this', 150, 215, { kind: 'title', px: 60, alpha: cardA, plate: null });
134	      const L = [[`weekly US survey averages: ${D('n_weeks')} from ${D('first_week_short')}`, ['n_weeks', 'first_week_short']],
135	        ['strong-credit borrowers; points and fees differ'], ['principal and interest only: no property taxes,'], ['insurance, PMI or tax deductions'],
136	        ['the bar is before taxes; no investment or market return tested'], ['value of the fallback in a job loss or emergency: not measured'],
137	        [`Tessa · ILLUSTRATIVE: rates of the week of ${D('last_week_short')},`, ['last_week_short']], [`on ${D('principal')} only`, ['principal']],
138	        ['US only · History, not a forecast · Not advice on which loan']];
139	      L.forEach(([s, cl], k) => label(O, s, 150, 290 + 60 * k, { kind: cl ? 'number' : 'compare', px: 48, alpha: cardA, plate: null, claims: cl,
140	        color: k === L.length - 1 ? (t > b.i1.say ? C.ink : '#C9D1DC') : '#C9D1DC' }));
141	      log.roi['i0.method'] = [120, 140, 1800, 820]; log.roi['i1.say'] = [140, 730, 1800, 790];
142	    }
143	    { const c = O.ctx; c.save(); c.font = '600 54px Inter'; const w1 = c.measureText('US only').width, w0 = c.measureText('US only · ').width, wAll = c.measureText('US only · history, not a forecast').width; c.restore();
144	      seg2(O, 96, 1024, 96 + w1, 1024, C.ink, 0.9 * show(t, b.i1.only, MV.m_w33.t1), 4); seg2(O, 96 + w0, 1024, 96 + wAll, 1024, C.ink, 0.9 * show(t, b.i1.history, MV.m_w33.t1), 4);
145	      log.roi['i1.only'] = [90, 960, 96 + w1 + 6, 1030]; log.roi['i1.history'] = [96 + w0 - 6, 960, 96 + wAll + 6, 1030]; }
146	    // S33: chữ trên hai thẻ → một thẻ; giá tuần
147	    for (const [card, s, cl, at, id] of [[card15, `${D('term_short')} mortgage`, ['term_short'], b.j1.fifteen, 'j1.fifteen'], [card30, `${D('term_long')} paid ${D('paid_in_short')}`, ['term_long', 'paid_in_short'], b.j1.thirty, 'j1.thirty']]) {
148	      const [x, y] = sc(card.position.x, card.position.y, 0.05);
149	      label(O, s, x, y + 16, { align: 'center', kind: 'number', px: 48, alpha: ok * show(t, at) * (1 - ease(t, b.j2.plus - 0.3, b.j2.plus)), claims: cl });
150	      log.roi[id] = [x - 300, y - 60, x + 300, y + 60];
151	    }
