const PER_PCT = 0.3, GAP_U = 1 / 500;   // thanh: 0,3/điểm % (như S25); hộp cushion: 1/500 đơn vị mỗi $/tháng của khoảng chênh khoản trả

export async function boot(res) {
  const poses = {
