1	// Tập 7 · C4 · TIỆN ÍCH CHUNG cho bảy đoạn thế giới của tập (world/c4/<đoạn>/scene.js). Không đổi thư viện nhà máy (lib3d.js / core.js).
2	// Gốc: world/c3kit.js (Tessa + nhà, the stack, nhãn, lớp bắt buộc — C3 đã duyệt) + phần mới của C4: Tessa CỬ ĐỘNG (tay + nghiêng người, hàng chờ C4
3	// gates/C3.md §3 #1), vật khoản vay riêng gắn với nhà (LoanTag, S01), thẻ hai khoản (V4 adapted, S02–S03), dải tuần (V1 xem trước, S02), lớp bắt buộc
4	// có đối trọng, cảnh khung cho đoạn chưa dựng. Mốc giờ CHỈ từ spine.json của đoạn; hằng số ở đây = hình học + độ dài hiệu ứng chung.
5	import * as THREE from 'three';
6	import { Studio, Stack, setOpacity, PALETTE } from '/toolkit/factory/world/lib3d.js';
7	import { Camera, Stage, loadJSON, fonts, C, CK, ease, lin, mix, rgba } from '/toolkit/factory/world/core.js';
8	import { home, nameTag, theStack, stackSet, BUNDLE_TH, label, brace, modeLook, FIG } from '/episodes/ep007/world/c3kit.js';
9	
10	export const POP = 0.2, PLATE = '#0B0E13';
11	// màu nhận diện (không mang nghĩa dữ liệu) — contract.json characters: Tessa = PALETTE.person2 (C3), Leo = PALETTE.person1
12	export const CHAR = { tessa: FIG, leo: PALETTE.person1 };
13	export const kf = (k, t) => { if (!k || !k.length) return 0; if (t <= k[0][0]) return k[0][1];
14	  for (let i = 1; i < k.length; i++) if (t <= k[i][0]) { const [a, x] = k[i - 1], [b, y] = k[i]; return b > a ? x + (y - x) * (t - a) / (b - a) : y; }
15	  return k[k.length - 1][1]; };
16	// hiện từ mốc a (dốc POP), tắt từ mốc z (dốc 0,3 s) nếu có
17	export const show = (t, a, z = Infinity) => (a == null ? 0 : ease(t, a - 0.05, a + POP) * (1 - ease(t, z, z + 0.3)));
18	export const pulse = (t, a, d = 0.6) => (a == null || t < a ? 0 : Math.max(0, 1 - (t - a) / d));
19	
20	export async function setup(seg, res, poses, { shadowBox = 16 } = {}) {
21	  const [S, CL] = await Promise.all([loadJSON(seg + 'spine.json'), loadJSON('/episodes/ep007/world/claims.json')]);
22	  await fonts();
23	  const cue = {}; for (const b of S.beats) cue[b.id] = { ...b.cues, t0: b.t0, t1: b.t1 };
24	  const MV = {}; for (const m of S.moves) MV[m.id] = m;
25	  const st = Stage(res), scene = new THREE.Scene(), { floor, key } = Studio(scene, { shadowBox });
26	  const D = (k) => CL[k].display;
27	  return { S, CL, D, G: CL._geom, cue, MV, st, O: st.O, renderer: st.renderer, scene, floor, key, CAM: Camera(poses, S.moves) };
28	}
29	// đèn chính theo điểm nhìn (bóng có ở mọi khu của đoạn dài)
30	export function followLight(key, tgt) {
31	  key.target.position.set(tgt[0], Math.max(0, tgt[1]), tgt[2]); key.position.set(tgt[0] - 6, Math.max(0, tgt[1]) + 14, tgt[2] + 10); key.target.updateMatrixWorld();
32	}
33	
34	// ================================================================ Tessa có cử động (hàng chờ C4 #1: "đứng yên cả 5 đoạn ở chế độ đồ thị")
35	// Người W4 tròn xoay → quay đầu không thấy được từ chính diện. Cử động đọc được ở máy chính diện: (1) NGHIÊNG người về phía vật (xoay quanh trục
36	// nhìn), (2) GIƠ TAY (cánh tay viên nang cùng màu, buông dọc thân lúc nghỉ) về phía vật, (3) gật nhẹ (đầu hạ 0,03). Mỗi cử động = một sự kiện
37	// {t, kind: 'arm'|'lean'|'nod', to: x thế giới của vật, hold} trong spine (S.gestures) — đúng lúc vật chạm/dâng.
38	export function figure(scene, opts) {
39	  const hm = home(scene, opts), p = hm.person, h = hm.h;
40	  const body = p.children[0], head = p.children[1];
41	  // nhân vật thứ hai (Leo, S29–S33): màu nhận diện riêng (contract.json characters) + tên trong khai trang kiểm
42	  if (opts.color) { body.material = body.material.clone(); body.material.color.set(opts.color); head.material = body.material; }
43	  if (opts.char) p.userData.checks = { role: 'mark', char: opts.char, key: `person-${opts.char.toLowerCase()}` };
44	  hm.char = opts.char || 'Tessa';
45	  const m = body.material;
46	  const pivot = new THREE.Group(); pivot.position.set(0, h * 0.66, 0); p.add(pivot);
47	  const arm = new THREE.Mesh(new THREE.CapsuleGeometry(h * 0.045, h * 0.3, 4, 8), m); arm.position.y = -(h * 0.15 + h * 0.045); arm.castShadow = true; pivot.add(arm);
48	  hm.pivot = pivot; hm.head = head; hm.headY = head.position.y; hm.body = body;
49	  // cánh tay nghỉ: sát thân về phía vật gần nhất (bên phải nếu không có sự kiện)
50	  pivot.position.x = h * 0.17;
51	  return hm;
52	}
53	export function gesture(hm, t, G = []) {
54	  let lean = 0, arm = 0, nod = 0, side = 1;
55	  for (const g of G) {
56	    const a = ease(t, g.t - 0.12, g.t + 0.28) * (1 - ease(t, g.t + (g.hold ?? 1.2), g.t + (g.hold ?? 1.2) + 0.45));
57	    if (a <= 0) continue;
58	    const s = Math.sign((g.to ?? hm.person.position.x + 1) - hm.person.position.x) || 1;
59	    if (g.kind === 'arm') { if (a > arm) { arm = a; side = s; } lean = Math.max(lean, 0.35 * a); }
60	    else if (g.kind === 'lean') { if (a > lean) side = s; lean = Math.max(lean, a); }
61	    else nod = Math.max(nod, a);
62	  }
63	  const p = hm.person, h = hm.h;
64	  p.rotation.z = -side * 0.16 * lean;
65	  hm.pivot.position.x = side * h * 0.17;
66	  hm.pivot.rotation.z = side * (0.1 + 2.25 * arm);          // buông (0,1 rad ra ngoài) → giơ chéo lên về phía vật
67	  hm.head.position.y = hm.headY - 0.035 * Math.sin(Math.PI * Math.min(1, nod * 1.0));
68	}
