1	// Tập 7 · C4 · kiểm khai scene.js KHÔNG render (không WebGL, không Playwright): chạy frame(t) mỗi 0,1 s với three thật + renderer giả + canvas 2D giả.
2	// Mẫu: episodes/ep006/c4/smoke/run.mjs. Báo: lỗi JS, vi phạm quy tắc 1 (log.violations của core.js), chữ < 48 px, hộp chữ giao nhau (đo gần đúng
3	// 0,55 em/ký tự), nhãn hiện < max(1 s, từ/3), chữ số trên hình không thuộc display của c4/gen/claims.json, và GIỜ HIỆN của mỗi nhãn trong
4	// label_cues so với cue của spine (đồng bộ dự kiến, ±0,2 s).  Dùng: node --import ./episodes/ep007/c4/smoke/register.mjs episodes/ep007/c4/smoke/run.mjs <đoạn> [bước s]
5	// Cần three: (cd toolkit/factory/world/vendor && npm ci).
6	import fs from 'node:fs';
7	const ROOT = '/home/user/crux-lab';
8	function ctx2d(cv) {
9	  let T = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 }; const st = [];
10	  const px = () => { const m = /(\d+(?:\.\d+)?)px/.exec(c.font || ''); return m ? +m[1] : 10; };
11	  const c = new Proxy({
12	    font: '10px Inter', canvas: cv, globalAlpha: 1, fillStyle: '#000', strokeStyle: '#000', lineWidth: 1,
13	    setTransform(a, b, cc, d, e, f) { if (typeof a === 'object') T = { ...a }; else T = { a, b, c: cc, d, e, f }; },
14	    getTransform() { return { ...T }; }, save() { st.push({ ...T }); }, restore() { if (st.length) T = st.pop(); },
15	    measureText(s) { return { width: String(s).length * px() * 0.55 }; },
16	    createLinearGradient() { return { addColorStop() {} }; }, createRadialGradient() { return { addColorStop() {} }; },
17	    getImageData(x, y, w, h) { return { data: new Uint8ClampedArray(w * h * 4), width: w, height: h }; }, putImageData() {}, createImageData(w, h) { return { data: new Uint8ClampedArray(w * h * 4), width: w, height: h }; },
18	  }, { get(o, k) { if (k in o) return o[k]; return () => {}; }, set(o, k, v) { o[k] = v; return true; } });
19	  return c;
20	}
21	globalThis.document = {
22	  createElement(tag) { const cv = { width: 300, height: 150, style: {}, getContext() { return this._c || (this._c = ctx2d(this)); }, addEventListener() {} }; return cv; },
23	  body: { appendChild() {} }, fonts: { load: async () => [], ready: Promise.resolve() },
24	};
25	globalThis.window = globalThis;
26	globalThis.fetch = async (u) => ({ json: async () => JSON.parse(fs.readFileSync(ROOT + u, 'utf8')) });
27	const seg = process.argv[2], step = +(process.argv[3] || 0.1), DUMP = (process.argv[4] || '').split(',').filter(Boolean).map(Number);   // đối số 3 "6,13.5": in chữ + roi ở các giờ đó (stderr)
28	const S = JSON.parse(fs.readFileSync(`${ROOT}/episodes/ep007/world/c4/${seg}/spine.json`, 'utf8'));
29	const mod = await import(`file://${ROOT}/episodes/ep007/world/c4/${seg}/scene.js`);
30	const { frame } = await mod.boot(108);
31	const viol = [], small = [], over = [], err = [], offframe = []; const vis = new Map(), first = new Map();
32	const CLA = JSON.parse(fs.readFileSync(`${ROOT}/episodes/ep007/c4/gen/claims.json`, 'utf8')).claims.map((c) => String(c.display)).filter((d) => /\d/.test(d)).sort((a, b) => b.length - a.length);
33	let n = 0, chart5 = 0;
34	for (let t = 0; t <= S.total + 1e-6; t += step) {
35	  let log;
36	  try { log = frame(+t.toFixed(3)); } catch (e) { err.push([t.toFixed(2), String(e.stack).split('\n').slice(0, 3).join(' | ')]); if (err.length > 3) break; continue; }
37	  n++; globalThis.NT = (globalThis.NT || 0) + (log.texts || []).length;
38	  if (DUMP.some((d) => Math.abs(d - t) < step / 2)) console.error(t.toFixed(2), 'cw', log.chartW, JSON.stringify((log.texts || []).filter((x) => x.opacity > 0.05).map((x) => [x.text, x.box.map(Math.round), x.opacity])), 'roi', JSON.stringify(log.roi));
39	  if (t < 5.0 && log.chartW > 0.01) chart5++;
40	  for (const v of log.violations || []) viol.push([+t.toFixed(2), v.text, v.chartW]);
41	  const tx = (log.texts || []).filter((x) => x.opacity > 0.3);
42	  const seen = new Set(tx.filter((x) => x.opacity > 0.5 && x.kind !== 'chrome').map((x) => x.text));
43	  for (const k of seen) { const v = vis.get(k) || { run: 0, best: 0, last: -9 }; v.run = (t - v.last < step * 1.5) ? v.run + step : step; v.last = t; v.best = Math.max(v.best, v.run); vis.set(k, v); if (!first.has(k)) first.set(k, +t.toFixed(2)); }
44	  for (const x of tx) if (x.kind !== 'chrome' && x.px < 48) small.push([+t.toFixed(2), x.text, x.px]);
45	  for (const x of tx) if (x.kind !== 'chrome' && (x.box[0] < 90 || x.box[2] > 1830 || x.box[1] < 50 || x.box[3] > 1030)) offframe.push([+t.toFixed(2), x.text, x.box]);
46	  for (let i = 0; i < tx.length; i++) for (let j = i + 1; j < tx.length; j++) {
47	    const A = tx[i].box, B = tx[j].box, w = Math.min(A[2], B[2]) - Math.max(A[0], B[0]), h = Math.min(A[3], B[3]) - Math.max(A[1], B[1]);
48	    if (w > 4 && h > 4) over.push([+t.toFixed(2), tx[i].text, tx[j].text]);
49	  }
50	}
51	const uniq = (a, k) => { const m = new Map(); for (const x of a) { const key = k(x); if (!m.has(key)) m.set(key, x); } return [...m.values()]; };
