1	// Tập 7 · C4 · ĐOẠN D = S16–S20. Hàng chồng theo tuần (đoạn c) tách bốn nhóm thập kỷ; trước mỗi nhóm một chồng điển hình (W2, bó của the stack);
2	// đường lãi 30 năm (accent, dải thấp sát sàn) chạy dọc hàng: lãi tụt mạnh vào 2010s trong khi chồng 2010s cao hơn 1990s (vạch nét đứt) → bốn ngoặc khoảng chênh
3	// (V6, cùng thang cột khoảng chênh của đoạn c) khớp chồng, không khớp đường lãi → 2020s gần ngang the stack của Tessa → về thế giới. Mốc giờ: spine.json.
4	import { setup, figure, gesture, figTag, WeekRow, theStack, stackSet, BUNDLE_TH, modeLook, followLight, chrome, label, seg2, vbrace, dip,
5	  show, pulse, C, ease, lin, mix, THREE } from '/episodes/ep007/world/c4kit.js';
6	import { Ribbon } from '/toolkit/factory/world/lib3d.js';
7	
8	const SEG = '/episodes/ep007/world/c4/d-s16-s20/';
9	// vòng bố cục 1 (verify CHẶN F-2: đường lãi xuyên thẻ thập kỷ): đường lãi nằm ở DẢI THẤP sát sàn (py ≈ 740–840 ở 1080, sau bốn chồng),
10	// thẻ thập kỷ là khối 3 dòng (tên · giá · khoảng chênh) PHÍA TRÊN chồng, ngoặc và vạch của Tessa → không đường nào đi qua chữ
11	const RB = 0.1375, RY = 0.133;
12	
13	export async function boot(res) {
14	  const poses = {
15	    wD0: { pos: [-7.4, 2.9, 10.4], tgt: [1.8, 1.2, -0.8], fov: 46, chart: 0 },
16	    // lùi nhẹ + dời phải (≈ 110 px/đơn vị ở chồng, sàn py ≈ 899): khối thẻ 2020s và 2010s không chạm nhau, chồng 2020s trong vùng an toàn
17	    cD: { pos: [2.6, 3.264, 26], tgt: [2.6, 3.264, 0], fov: 22.39, chart: 1 },
18	    wEnd: { pos: [-7.6, 2.6, 7.6], tgt: [-2.4, 1.0, 0], fov: 38, chart: 0 },
19	  };
20	  const { S, D, G, cue, MV, st, O, renderer, scene, floor, key, CAM } = await setup(SEG, res, poses);
21	  const b = cue, X = S.x, N = S.weeks.length, W = X.x1 - X.x0, U = BUNDLE_TH / G.bundle_usd;
22	  const GS = G.stack_total * U / S.spread_now, dec = (i) => (i < S.rng[1][0] ? 0 : i < S.rng[2][0] ? 1 : i < S.rng[3][0] ? 2 : 3);
23	  const hm = figure(scene, { x: X.house }), tstack = theStack(scene, G, { x: X.stack });
24	  stackSet(tstack, G.stack_total);
25	  const row = WeekRow(scene, S.extra, { x0: X.x0, width: W, z: 0.05, depth: 0.22, unit: U });
26	  const xc = (k) => X.x0 + (S.rng[k][0] + S.rng[k][1]) / 2 / N * W, xw = (i) => X.x0 + (i + 0.5) * W / N;
27	  const stacks = [0, 1, 2, 3].map((k) => theStack(scene, G, { x: xc(k) + (k - 1.5) * X.split, z: X.zs }));
28	  stacks.forEach((s, k) => { s.userData.checks = { role: 'bar', series: 'era-median', key: `era-stack-${k}` }; });
29	  const l30 = Ribbon({ color: C.accent, z: 0.6, width: 0.055, maxPts: N }), l10 = Ribbon({ color: '#9CC0FF', z: 0.62, width: 0.11, maxPts: N });
30	  scene.add(l30, l10); l30.userData.checks = { role: 'series', series: 'r30', key: 'rate-30' };
31	  const LAB = [[D('era1991_span'), D('era1991_median_r30'), D('era1991_median_extra_total'), ['era1991_span', 'era1991_median_r30'], 'era1991_median_extra_total', D('era1991_median_spread'), 'era1991_median_spread'],
32	    [D('era2000_name'), D('era2000_median_r30'), D('era2000_median_extra_total'), ['era2000_name', 'era2000_median_r30'], 'era2000_median_extra_total', D('era2000_median_spread'), 'era2000_median_spread'],
33	    [D('era2010_name'), D('era2010_median_r30'), D('era2010_median_extra_total'), ['era2010_name', 'era2010_median_r30'], 'era2010_median_extra_total', D('era2010_median_spread'), 'era2010_median_spread'],
34	    [D('era2020_name'), null, D('era2020_median_extra_total'), ['era2020_name'], 'era2020_median_extra_total', D('era2020_median_spread'), 'era2020_median_spread']];
35	  const tagAt = [b.e1.fifteen, b.e2.fourteen, b.e3.twenty, b.e6.one], brAt = [b.e4.four, b.e4.four + 0.25, b.e4.seven, b.e4.seven + 0.25];
36	  const cW = new THREE.Color(C.warn), cWd = new THREE.Color('#4A3F2A');
37	
38	  function frame(t) {
39	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
40	    followLight(key, pose.tgt); modeLook(scene, floor, cw); gesture(hm, t, S.gestures);
41	    const sp = ease(t, b.e0.decade - 0.05, b.e0.decade + 0.9), dx = (i) => (dec(i) - 1.5) * X.split * sp;
42	    // nhóm đang nói sáng; S19 cả bốn như nhau; sau S20 về thế giới cả hàng tối nhẹ
43	    const cur = t < S.up[0] ? -1 : t < S.up[1] ? 0 : t < S.up[2] ? 1 : t < b.e4.gap ? 2 : t < S.up[3] ? 9 : 3;
44	    // từ S19 ý là BỐN CHỒNG + ngoặc: hàng tuần mờ hẳn (nền sạch cho thẻ, ngoặc); về thế giới thì hiện lại
45	    const rowA = 1 - 0.85 * ease(t, b.e4.gap - 0.3, b.e4.gap + 0.5) * (1 - ease(t, MV.m_w20.t0, MV.m_w20.t1));
46	    row.set({ grow: 1, dx, a: rowA, color: (i, c) => { const d = dec(i), on = cur === -1 || cur === 9 ? 0.55 : d === cur ? 1 : 0.3; c.copy(cWd).lerp(cW, on); } });
47	    stacks.forEach((s, k) => stackSet(s, S.med[k] * ease(t, S.up[k], S.up[k] + 1.1)));
48	    // đường lãi 30 năm, dải thấp sát sàn (dời theo nhóm); đoạn 2010s loé ở "far" (lãi thấp hẳn) và "lower". Vào cùng cú chuyển sang đồ thị,
49	    // tắt sau S19.2 (ý "lãi thấp hơn" đã nói xong) — S20 chỉ còn chồng, ngoặc và the stack của Tessa
50	    const pts = [], p10 = []; for (let i = 0; i < N; i += 2) { const p = [xw(i) + dx(i), RB + S.r30[i] * RY]; pts.push(p); if (dec(i) === 2) p10.push(p); }
51	    const rA = ease(t, MV.m_c16.t0, MV.m_c16.t1) * (1 - ease(t, b.e6.twenty - 0.2, b.e6.twenty + 0.4));
52	    l30.set(pts); l30.visible = rA > 0.01; l30.material.opacity = rA * (0.75 + 0.25 * pulse(t, b.e5.lower, 1.0));
53	    const hA = rA * Math.max(pulse(t, b.e3.far, 1.6), pulse(t, b.e5.lower, 1.2)); l10.set(p10); l10.visible = hA > 0.01; l10.material.opacity = hA;
54	    renderer.render(scene, cam);
55	    // ---------------- lớp phủ
56	    const log = O.begin(t, cw, cam), ok = cw >= 0.95 ? 1 : 0; log.roi = {};
57	    dip(O, 1 - ease(t, 0, 0.4));
58	    figTag(O, hm);
59	    const sc = (x, y, z = 0) => O.toScreen(x, y, z), [, yF] = sc(X.x0, 0, X.zs), [xL] = sc(X.x0, 0, 0.05), [xR] = sc(X.x1, 0, 0.05), end = MV.m_w20.t0 - 0.05;
60	    const top = (k) => sc(stacks[k].position.x, S.med[k] * U, X.zs);
61	    // khung bố cục (px 1080, chỉ đọc khi ở đồ thị): ngoặc k = cạnh TRÁI chồng k (0,62), cao ×1,06 khi rung; đường của Tessa = đỉnh the stack.
62	    // Đáy khối thẻ k (anchor) = trên đỉnh chồng, đỉnh ngoặc và vạch của Tessa → ba dòng (tên y−142 · giá y−86 · khoảng chênh y−30) không bị
63	    // đường nào cắt; dây dẫn mảnh từ đáy khối xuống đỉnh chồng (chồng thấp: khối nổi cao hơn đỉnh)
64	    const bxOf = (k) => stacks[k].position.x - 0.62, [sx, sy] = sc(X.stack + 0.45, G.stack_total * U, 0), [tx] = sc(X.stack, 0);
65	    const anchor = (k) => Math.min(top(k)[1], sc(bxOf(k), S.spd[k] * GS * 1.07, X.zs)[1], sy - 14) - 8;
66	    const tagX = (k) => { const x = top(k)[0]; return k === 0 ? x + 30 : k === 3 ? Math.min(x, 1684) : x; };   // 1990s: xa dây nối của Tessa; 2020s: trong vùng an toàn
67	    const [, rTop] = sc(0, RB + 9.5 * RY, 0.6), [, rBot] = sc(0, RB + 2.5 * RY, 0.6);
68	    log.roi['e0.decade'] = [xL, sc(0, 3.6)[1], xR, yF];
69	    // nhãn trên (thập kỷ đang nói) + khối thẻ trên mỗi chồng điển hình (giữ tới hết)
70	    for (let k = 0; k < 4; k++) {
71	      const [name, rate, usd, cl, cu, , ] = LAB[k], nx = k < 3 ? S.up[k + 1] - 0.1 : end, [x, y] = top(k), ay = anchor(k), xt = tagX(k);
72	      log.roi[['e1.typical', 'e2.y2000s', 'e3.y2010s', 'e6.twenty'][k]] = [x - 70, y - 20, x + 70, yF];
73	      if (k < 3) {
74	        // 2010s tắt hẳn trước khi "typical gap…" hiện cùng chỗ (verify WARN 29 s: hai nhãn chồng lúc chuyển)
75	        const z = k === 2 ? b.e4.gap - 0.4 : nx;
76	        label(O, `${name}: rate near ${rate}`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, tagAt[k], z), claims: cl });
77	        label(O, `typical stack ${usd}`, 960, 268, { align: 'center', kind: 'number', alpha: ok * show(t, tagAt[k], z), claims: [cu] });
78	        log.roi[['e1.fifteen', 'e2.fourteen', 'e3.twenty'][k]] = [500, 150, 1420, 290];
79	      }
80	      const ta = ok * show(t, tagAt[k], end);
81	      label(O, name, xt, ay - 142, { align: 'center', kind: 'number', px: 48, alpha: ta, claims: [cl[0]] });
82	      label(O, usd, xt, ay - 86, { align: 'center', kind: 'number', px: 48, alpha: ta, claims: [cu] });
83	      seg2(O, x, ay - 4, x, y - 6, C.muted, 0.6 * ta, 2);
84	    }
85	    // S18 "more": vạch nét đứt từ đỉnh chồng 1990s sang chồng 2010s (dưới mọi khối thẻ)
86	    { const [x0, y0] = top(0), [x2] = top(2), a = ok * show(t, b.e3.more, b.e4.gap - 0.1);
87	      seg2(O, x0 + 55, y0, mix(x0 + 55, x2 + 60, lin(t, b.e3.more, b.e3.more + 0.5)), y0, C.ink, 0.85 * a, 4, [14, 10]);
88	      log.roi['e3.more'] = [x0, y0 - 30, x2 + 70, y0 + 30]; log.roi['e3.far'] = [sc(xc(2) - 1.5, 0)[0], rTop - 10, sc(xc(2) + 1.5, 0)[0], rBot + 10]; }
89	    // S19: bốn ngoặc khoảng chênh (accent) sát cạnh trái mỗi chồng điển hình; số khoảng chênh = dòng thứ ba của khối thẻ (cùng màu ngoặc)
90	    label(O, `typical gap: ${D('term_long')} minus ${D('term_short')} rate`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, b.e4.gap, S.up[3] - 0.1), claims: ['term_long', 'term_short'] });
91	    log.roi['e4.gap'] = [400, 150, 1520, 230];
92	    for (let k = 0; k < 4; k++) {
93	      const bx = bxOf(k), h = S.spd[k] * GS * (1 + 0.06 * Math.sin(12 * (t - b.e7.moved)) * pulse(t, b.e7.moved, 1.4));
94	      const [x, y0] = sc(bx, 0, X.zs), [, y1] = sc(bx, h, X.zs), a = ok * show(t, brAt[k], end), ay = anchor(k), xt = tagX(k);
95	      vbrace(O, x, y1, y0, C.accent, a * (0.8 + 0.2 * pulse(t, b.e5.wider, 1.0)), 6 + 3 * pulse(t, b.e5.wider, 1.0), -14);
96	      label(O, LAB[k][5], xt, ay - 30, { align: 'center', kind: 'number', px: 48, color: '#A9C6FF', alpha: a, claims: [LAB[k][6]] });
97	      if (k === 2) log.roi['e4.seven'] = [x - 20, ay - 80, xt + 150, y0];
