284	    for (let i = 0; i < nmax; i++) {
285	      const [x, z] = pos(i), isLate = i >= n, c = Math.floor(i / cols), a = isLate ? cl(late - (i - n)) : cl(lit - i);
286	      if (a <= 0.002) { tiles.setMatrixAt(i, hide); continue; }
287	      if (isLate) { M.makeScale(1.2, 2.5, 1.2).setPosition(x, th * 2.5 / 2, z); col.copy(K.empty).lerp(K.warn, a * (0.85 + 0.15 * pulse)); }
288	      else { M.makeScale(1, a, 1).setPosition(x, th * a / 2, z); col.copy(K.req).lerp(K.dark, arr(cover, c)).lerp(K.ink, 0.8 * arr(flash, c)); }
289	      tiles.setMatrixAt(i, M); tiles.setColorAt(i, col);
290	    }
291	    for (let i = 0; i < n; i++) {
292	      const c = Math.floor(i / cols), r = i % cols, d = arr(drop, c) * cl(lit - i), [x, z] = pos(i);
293	      if (d <= 0.002) { slabs.setMatrixAt(i, hide); continue; }
294	      const k = cols - 1 - r, dl = 0.35 * k / (cols - 1), e = sm(cl((arr(gathered, c) - dl) / (1 - dl))), fall = sm(d);
295	      const y0 = th + slab / 2 + 0.004, y1 = th + 0.004 + k * (slab + SG) + slab / 2;
296	      let y = y0 + (y1 - y0) * e + 0.08 * Math.sin(Math.PI * e) + (1 - fall) * DROP;
