import sys, math, json
import numpy as np
P = {'wT0': ([-5.2, 3.4, 7.0], [1.7, 0, -1.8], 40), 'wT': ([-4.0, 4.2, 5.8], [1.9, 0, -2.0], 40),
     'cQ': ([2.2, 5.4, 5.9], [2.5, 0.3, -1.9], 52), 'cW': ([6.1, 3.0, 3.2], [6.4, 0.1, -1.3], 40)}
def proj(pose, p):
    e, t, fov = P[pose]; e, t, p = map(np.array, (e, t, p))
    f = t - e; f /= np.linalg.norm(f); r = np.cross(f, [0, 1, 0]); r /= np.linalg.norm(r); u = np.cross(r, f)
    d = p - e; x, y, z = d @ r, d @ u, d @ f
    th = math.tan(math.radians(fov) / 2)
    return round((x / (z * th * 16 / 9) + 1) * 960), round((1 - y / (z * th)) * 540)
pts = json.loads(sys.argv[2])
for p in pts: print(p, proj(sys.argv[1], p))

